[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$g=Get-Content (Join-Path $Path 'reference-graph.json') -Raw|ConvertFrom-Json;$nodes=@($g.nodes);if(@($nodes|Sort-Object -Unique).Count -ne $nodes.Count){throw 'GRAPH_DUPLICATE_NODE_ID'};$set=@{};foreach($n in $nodes){$set[$n]=$true};$adj=@{};foreach($n in $nodes){$adj[$n]=@()};foreach($e in @($g.edges)){if(-not $set.ContainsKey($e.from)-or-not $set.ContainsKey($e.to)){throw 'GRAPH_DANGLING_REFERENCE'};$adj[$e.from]+=$e.to};function Visit([string]$n,[hashtable]$visiting,[hashtable]$done){if($visiting[$n]){throw 'GRAPH_CYCLE_DETECTED'};if($done[$n]){return};$visiting[$n]=$true;foreach($next in @($adj[$n])){Visit $next $visiting $done};$visiting.Remove($n);$done[$n]=$true};$vis=@{};$done=@{};foreach($n in $nodes){Visit $n $vis $done};Write-Host 'PASS: Reference graph has unique IDs, no dangling edges and no cycles.'
